SELECT s.market_regime, s.decision AS entry_decision, COUNT(*) AS n, SUM(p.realized_pnl>0) AS wins, SUM(p.realized_pnl<0) AS losses, SUM(p.status='STOPPED') AS stopped, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_gross_pct FROM paper_position p JOIN trade_signal s ON s.id=p.signal_id WHERE p.opened_at>='2026-10-11 00:00:00' AND p.status IN ('CLOSED','STOPPED') GROUP BY s.market_regime, s.decision ORDER BY n DESC LIMIT 40;
SELECT w.execution_reason, CASE WHEN m.entry_quality_score<55 THEN 'a50-54' WHEN m.entry_quality_score<60 THEN 'b55-59' WHEN m.entry_quality_score<70 THEN 'c60-69' ELSE 'd70+' END AS eq_bucket, COUNT(*) AS n, SUM(p.realized_pnl>0) AS wins, SUM(p.realized_pnl<0) AS losses, SUM(p.status='STOPPED') AS stopped, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_gross_pct FROM paper_position p JOIN wallet_trade w ON w.signal_id=p.signal_id AND w.side='BUY' LEFT JOIN wallet_managed_position m ON m.entry_signal_id=p.signal_id WHERE p.opened_at>='2026-10-11 00:00:00' AND p.status IN ('CLOSED','STOPPED') GROUP BY w.execution_reason, eq_bucket ORDER BY w.execution_reason, eq_bucket LIMIT 60